// Count failure: count one failed run of a workflow in the error report's static data, per workflow name.
// The counters belong to one local day (GENERIC_TIMEZONE, UTC when unset): the first failure on a new day resets them.
// Runs before Build failure message. n8n saves static data only from a run that succeeds, so this count is kept only when
// this run's failure notice is delivered; if the notice fails, the run fails and the count is lost too (see the monitoring skill).
// The name defaults to 'unknown workflow', as in Build failure message. Other metrics are kept as they are.
function localDay(now, timeZone) {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
}

function countFailure(metrics, day, workflowName) {
  // A new day starts with empty counters and no alerts sent yet.
  const current = metrics?.day === day ? metrics : { ...(metrics ?? {}), day, counters: {}, alerted: {} };
  const counters = { ...(current.counters ?? {}) };
  const failures = { ...(counters.failures ?? {}) };
  failures[workflowName] = (failures[workflowName] ?? 0) + 1;
  counters.failures = failures;
  return { ...current, counters };
}

const data = $getWorkflowStaticData('global');
const payload = $input.first().json;
const day = localDay(new Date(), $env.GENERIC_TIMEZONE || 'UTC');
data.metrics = countFailure(data.metrics, day, payload.workflow?.name || 'unknown workflow');
return [{ json: payload }];

// Build failure message: turn one Error Trigger payload into a notify input {kind, title, body, url}.
// Body holds the failed node and the error message, cut to 1500 characters with '…' so it stays readable.
const LIMIT_BODY = 1500;
const LIMIT_TITLE = 200;

// Cut text to max characters (code points). Adds '…' only when it had to cut.
function clip(text, max) {
  const chars = Array.from(String(text ?? ''));
  return chars.length <= max ? chars.join('') : chars.slice(0, max - 1).join('') + '…';
}

const payload = $input.first().json;
const workflowName = payload.workflow?.name || 'unknown workflow';
const execution = payload.execution || {};
const error = execution.error || {};
// The failing node is on the error for node errors; otherwise the last node that ran is the best guess.
const nodeName = error.node?.name || execution.lastNodeExecuted || 'unknown node';
const message = error.message || 'no error message';

const body = clip(`Node: ${nodeName}\nError: ${message}`, LIMIT_BODY);
const title = clip(`Workflow failed: ${workflowName}`, LIMIT_TITLE);

return [{ json: { kind: 'failure', title, body, url: execution.url || '' } }];

// Build alert: once a workflow has failed more than ALERT_AFTER times today, build one alert for it (kind alert).
// Sent once per workflow per day: the key is kept in static data, which is saved only when this run succeeds.
// Returns no item for every other failure, so Notify alert does not run.
const ALERT_AFTER = 3;

const data = $getWorkflowStaticData('global');
const name = $('Error input').first().json.workflow?.name || 'unknown workflow';
const count = data.metrics?.counters?.failures?.[name] ?? 0;
const key = `failures:${name}`;
if (count <= ALERT_AFTER || data.metrics.alerted?.[key]) return [];
data.metrics.alerted = { ...(data.metrics.alerted ?? {}), [key]: true };

const title = `Repeated failures: ${name}`;
const body = `${count} failures today (alert above ${ALERT_AFTER}). The n8n executions list shows each one.`;
return [{ json: { kind: 'alert', title, body, url: '' } }];
